 "content": "def transform(grid):
    # Each contiguous non-background horizontal run is represented by its color
    # in a 2x3 catalog, with colors ordered numerically and empty cells padded.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    counts = {}
    for row in grid:
        i = 0
        while i < len(row):
            if row[i] == bg:
                i += 1
                continue
            color = row[i]
            counts[color] = counts.get(color, 0) + 1
            i += 1
            while i < len(row) and row[i] == color:
                i += 1
    values = []
    for color in sorted(counts):
        values.extend([color] * counts[color])
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
